cd /var/folders/4_/s6fbcjyn4b13xdxkd3lv0kw00000gn/T/arm-s1-pre-3-gxf5votn/data/s1-conversion/; python3 -I - <<'E' | tee ../../work/analysis.txt
import csv,collections as C
S=list(csv.DictReader(open('sessions.csv')));O=list(csv.DictReader(open('orders.csv')))
wk=lambda t:1 if t[:10]<='2026-06-07' else 2
n=C.Counter();ck=C.Counter()
for r in S:
    for k in [(wk(r['timestamp']),'all'),(wk(r['timestamp']),r['landing_page']),(wk(r['timestamp']),r['device'])]:
        n[k]+=1;ck[k]+=r['checkout_reached']=='yes'
orders=C.Counter(wk(r['timestamp']) for r in O)
for w in(1,2):print('wk',w,'sessions',n[(w,'all')],'orders',orders[w],'conv %.2f%%'%(100*orders[w]/n[(w,'all')]),'checkout %.2f%%'%(100*ck[(w,'all')]/n[(w,'all')]))
for k in sorted(n):
    if k[1]!='all':print(k,n[k],ck[k],'%.2f%%'%(100*ck[k]/n[k]))
# daily checkout rate by page
d=C.Counter();dc=C.Counter()
for r in S:
    k=(r['timestamp'][:10],'ss' if 'summer' in r['landing_page'] else 'other');d[k]+=1;dc[k]+=r['checkout_reached']=='yes'
for day in sorted({a for a,_ in d}):print(day,{p:'%d/%d=%.1f%%'%(dc[(day,p)],d[(day,p)],100*dc[(day,p)]/max(d[(day,p)],1)) for p in('other','ss')},'orders',sum(r['timestamp'][:10]==day for r in O))
# device x day for last days
for day in('2026-06-12','2026-06-13'):
    for dev in('desktop','mobile'):
        x=[r for r in S if r['timestamp'][:10]==day and r['device']==dev];print(day,dev,len(x),sum(r['checkout_reached']=='yes' for r in x),max(r['timestamp'] for r in x))
E

